    out = [row[:] for row in grid]
    # Downward V-shaped outlines enclose triangular interiors. Identify
    # apexes on the first row, then fill between the two diagonal sides.
    for c in range(w):
        if grid[0][c] == 0:
            continue
        for r in range(1, h):
            lo, hi = c-r, c+r
            if lo < 0:
                lo = 0
