 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Fill the space between matching-color boundary marks on each row.
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value != 0]
        if len(cols) >= 2:
            for c in range(cols[0] + 1, cols[-1]):
                if row[c] == 0:
                    out[r][c] = 2
    return out

